"""Applying partner discount codes to orders."""

from datetime import datetime, timezone

from app.models import Order
from app.repositories import discount_codes
from app.repositories import orders as orders_repo
from app.services.orders import OrderNotFound
from app.services.pricing import build_applied_discount


class CodeNotFound(Exception):
    pass


class CodeExpired(Exception):
    pass


class OrderNotDiscountable(Exception):
    """Order is no longer pending (e.g. already paid)."""


class DiscountAlreadyApplied(Exception):
    """Order already carries a different code; codes do not stack."""


async def apply_discount(order_id: str, raw_code: str) -> Order:
    now = datetime.now(timezone.utc)
    code = discount_codes.get_by_code(raw_code.strip().upper())
    if code is None:
        raise CodeNotFound(raw_code)
    if code.expires_at <= now:
        raise CodeExpired(code.code)

    doc = await orders_repo.get(order_id)
    if doc is None:
        raise OrderNotFound(order_id)
    if doc["status"] != "pending":
        raise OrderNotDiscountable(order_id)

    existing = doc.get("discount")
    if existing is not None:
        # Retrying the same code is idempotent; a different code is a conflict.
        if existing["code"] == code.code:
            return Order(**doc)
        raise DiscountAlreadyApplied(order_id)

    applied = build_applied_discount(doc["subtotal_paise"], code, now)
    new_total = doc["subtotal_paise"] - applied.amount_paise
    if not await orders_repo.set_discount(order_id, applied.model_dump(), new_total):
        # Lost a race (another discount or a payment landed first): re-evaluate.
        return await _resolve_lost_race(order_id, code.code)
    return await _reload(order_id)


