  if (!Number.isSafeInteger(paise)) {
    throw new Error(`formatPaise: expected an integer number of paise, got ${paise}`);
  }
  const negative = paise < 0;
  const abs = negative ? -paise : paise;
  const fraction = abs % 100;
  // abs - fraction is an exact multiple of 100, so this division is exact.
  const rupees = String((abs - fraction) / 100);

  // Indian grouping: last three digits, then groups of two.
  let grouped = rupees;
  if (rupees.length > 3) {
    const head = rupees.slice(0, -3);
    const tail = rupees.slice(-3);
    grouped = head.replace(/\\B(?=(\\d{2})+(?!\\d))/g, ",") + "," + tail;
  }
  return `${negative ? "-" : ""}₹${grouped}.${String(fraction).padStart(2, "0")}`;
}''')
